Definition shb (v : N) (k : Z) : expr :=
  if Z.eqb k 0 then EAlu ALU_SRL (EVar v) (ELit 3) else EAlu ALU_SRL (EAlu ALU_ADD (EVar v) (ELit k)) (ELit 3).
Definition shdj (v : N) (k : Z) : list kentry :=
  [KDisj (SA (shb v k) SHBASE) (ELit 1) (SA (EVar 32) 0) (ELit 392);
   KDisj (SA (shb v k) SHBASE) (ELit 1) (SA (EVar 33) (-8192)) (ELit 8192)].
Definition SHK : list (N * Z) :=
  [(32%N, 0); (32%N, 8); (32%N, 48); (32%N, 56); (32%N, 64); (32%N, 72); (32%N, 96); (32%N, 104); (32%N, 112);
   (32%N, 248); (32%N, 256); (32%N, 259); (36%N, 32); (37%N, 0); (38%N, 0)].
Definition kshd : list kentry := flat_map (fun vk => shdj (fst vk) (snd vk)) SHK.

Definition shz (v : N) (k : Z) : kentry := KWord (SA (shb v k) SHBASE) 1 (ELit 0).
Definition kshz : list kentry := map (fun vk => shz (fst vk) (snd vk)) SHK.

Definition shobj (v : N) : option (nat * Z) :=
  if N.eqb v 32 then Some (0%nat, 392) else if N.eqb v 36 then Some (4%nat, 48)
  else if N.eqb v 37 then Some (5%nat, 24) else if N.eqb v 38 then Some (6%nat, 24) else None.
Definition shk_okb (vk : N * Z) : bool :=
  match shobj (fst vk) with Some (_, n) => (0 <=? snd vk) && (snd vk + 8 <=? n) | None => false end.
