  Lemma ctor_call : forall (Q : machine_state -> Prop) R1 (pc1 : word) m1 RT SF DF (d n : Z) res (retpc : Z),
    rfull R1 -> rtbl Wc R1 RT -> ftbl Wc spz m1 SF -> ftbl Wc ds m1 DF -> Pw m1 -> mem_inv asegs m1 ->
    evt asegs (ipost R1 F fc d n (bv_unsigned (PropExec.getr R1 2)) res m1) (MS R1 F pc1 fc None m1 (seg_rom asegs)) ->
    ds <= d -> d + n <= ds + DS_SIZE -> 0 < n ->
    spz - 8192 <= bv_unsigned (PropExec.getr R1 2) - AINTRIN_STACK -> bv_unsigned (PropExec.getr R1 2) <= spz ->
    fin (-8192) 0 (fkeys SF) = true -> fin 0 DS_SIZE (fkeys DF) = true ->
    ret_pc (PropExec.getr R1 1) = Z_to_bv 64 retpc ->
    (forall R2 m2, rfull R2 -> rtbl Wc R2 (keptf RT) -> ftbl Wc spz m2 (fabove (bv_unsigned (PropExec.getr R1 2) - spz) SF) ->
       ftbl Wc ds m2 (fdrop (d - ds) n DF) -> Pw m2 ->
       mem_inv asegs m2 -> rw_cells asegs m2 d [CB (Z.to_nat n) res] ->
       evt asegs Q (MS R2 F (Z_to_bv 64 retpc) fc None m2 (seg_rom asegs))) ->
