  Lemma ctor_memcpy : forall (Q : machine_state -> Prop) R1 m1 RT SF DF (d sa : Z) src (retpc spc : Z),
    rfull R1 -> rtbl Wc R1 RT -> ftbl Wc spz m1 SF -> ftbl Wc ds m1 DF -> Pw m1 -> mem_inv asegs m1 ->
    PropExec.getr R1 10 = Z_to_bv 64 d -> PropExec.getr R1 11 = Z_to_bv 64 sa -> PropExec.getr R1 12 = Z_to_bv 64 24 ->
    PropExec.getr R1 2 = Z_to_bv 64 spc -> PropExec.getr R1 1 = Z_to_bv 64 retpc ->
    (sa = ppos \/ sa = pstr \/ sa = pstr2) -> bytes_at asegs m1 sa src -> length src = 24%nat ->
    ds <= d -> d + 24 <= ds + DS_SIZE ->
    spz - 8192 + AINTRIN_STACK <= spc -> spc <= spz -> 0 <= retpc < 2 ^ 64 -> retpc mod 2 = 0 ->
    fin (-8192) 0 (fkeys SF) = true -> fin 0 DS_SIZE (fkeys DF) = true ->
    (forall R2 m2, rfull R2 -> rtbl Wc R2 (keptf RT) -> ftbl Wc spz m2 (fabove (spc - spz) SF) -> ftbl Wc ds m2 (fdrop (d - ds) 24 DF) -> Pw m2 ->
       mem_inv asegs m2 -> rw_cells asegs m2 d [CB 24 src] ->
       evt asegs Q (MS R2 F (Z_to_bv 64 retpc) fc None m2 (seg_rom asegs))) ->
    evt asegs Q (MS R1 F (Z_to_bv 64 AASAN_MEMCPY) fc None m1 (seg_rom asegs)).
Proof.
